import json, pathlib, collections
root=pathlib.Path('.')
items=json.load(open('.direct_envs.json',encoding='utf-8'))
sections=collections.defaultdict(list)
for e in items:
    sections[e['section']].append(e)

def labels_for(section):
    return ', '.join(e['label'] for e in sections[section])

def loc_for(section):
    lst=sections[section]
    return f"main.tex:{lst[0]['line']}-{lst[-1]['end']} ({section})"

