for key in expected:
    if key=='valid':
        md += ['## valid', f'- `{inventory[key]}`', '']
        continue
    md.append('## '+key.replace('_',' ').title())
    rows=inventory[key]
    if not rows:
        md.append('- No items classified in this category.')
    for row in rows:
        md.append(f"- **Label:** `{row['label']}`")
